SELECT , 
FROM errand_order e

WHERE e.errand_order_id = #{orderId}

SELECT errand_order_id FROM errand_order
WHERE id > #{lastId}
ORDER BY id
LIMIT #{limit}

SELECT , , IFNULL(evc.view_count, 0) AS view_count FROM errand_order e
LEFT JOIN errand_view_count evc ON evc.errand_order_id = e.errand_order_id
AND e.state NOT IN ('DRAFT', 'DELETED')
AND e.type = #{type}
AND e.state = #{state}
ORDER BY
IFNULL(evc.view_count, 0) DESC, e.id DESC e.reward ASC, e.id ASC e.reward DESC, e.id DESC e.create_time ASC, e.id ASC e.create_time DESC, e.id DESC
LIMIT #{offset}, #{limit}


SELECT errand_order_id AS order_id, feed_time, price, view_count
FROM errand_feed_index
WHERE state = 'PUBLISHED'



            AND (view_count < #{cursor.viewCount}
                OR (view_count = #{cursor.viewCount} AND errand_order_id < #{cursor.orderId}))


            AND (feed_time > #{cursor.feedTime}
                OR (feed_time = #{cursor.feedTime} AND errand_order_id > #{cursor.orderId}))


            AND (price > #{cursor.price}
                OR (price = #{cursor.price} AND errand_order_id > #{cursor.orderId}))


            AND (price < #{cursor.price}
                OR (price = #{cursor.price} AND errand_order_id < #{cursor.orderId}))


            AND (feed_time < #{cursor.feedTime}
                OR (feed_time = #{cursor.feedTime} AND errand_order_id < #{cursor.orderId}))



ORDER BY

    view_count DESC, errand_order_id DESC
    feed_time ASC, errand_order_id ASC
    price ASC, errand_order_id ASC
    price DESC, errand_order_id DESC
    feed_time DESC, errand_order_id DESC

LIMIT #{limit}

SELECT COUNT(1)
FROM errand_order e

    AND e.state NOT IN ('DRAFT', 'DELETED')

        AND e.type = #{type}


        AND e.state = #{state}

SELECT lock_seq
FROM errand_order
WHERE errand_order_id = #{orderId}

mapper.update:
UPDATE errand_order
SET state      = 'CONFIRMED',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND taker_id = #{takerId}
  AND state = 'LOCKED'

UPDATE errand_order
SET state      = 'PICKED_UP',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND taker_id = #{takerId}
  AND state = 'CONFIRMED'

UPDATE errand_order
SET state      = 'DELIVERED',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND taker_id = #{takerId}
  AND state = 'PICKED_UP'

UPDATE errand_order
SET state      = 'COMPLETED',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND publisher_id = #{publisherId}
  AND state = 'DELIVERED'

UPDATE errand_order
SET state      = 'CANCELLED',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND publisher_id = #{publisherId}
  AND state IN ('PENDING_PAYMENT', 'PENDING_REVIEW', 'PUBLISHED', 'LOCKED', 'CONFIRMED')

UPDATE errand_order
SET state      = 'PENDING_PAYMENT',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND publisher_id = #{publisherId}
  AND state = 'DRAFT'

UPDATE errand_order
SET state      = 'DELETED',
    update_time = NOW()
WHERE errand_order_id = #{orderId}
  AND publisher_id = #{publisherId}
  AND state = 'DRAFT'

mapper.select:
SELECT errand_order_id
FROM errand_order
WHERE state = 'PENDING_PAYMENT'
  AND update_time <= #{before}
LIMIT #{limit}

SELECT errand_order_id
FROM errand_order
WHERE state = 'PENDING_REVIEW'
  AND update_time <= #{before}
LIMIT #{limit}

SELECT errand_order_id
FROM errand_order
WHERE state = 'DELIVERED'
  AND update_time <= #{before}
LIMIT #{limit}

SELECT , 
FROM errand_order e

WHERE e.publisher_id = #{userId}
  AND e.state != 'DELETED'

    AND e.state = #{state}

ORDER BY e.create_time DESC, e.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM errand_order
WHERE publisher_id = #{userId}
  AND state != 'DELETED'

    AND state = #{state}

SELECT , 
FROM errand_order e

WHERE e.publisher_id = #{userId}
  AND e.state IN ('PUBLISHED', 'LOCKED', 'CONFIRMED')
ORDER BY e.create_time DESC, e.id DESC
LIMIT #{offset}, #{limit}

SELECT , 
FROM errand_order e

WHERE e.taker_id = #{userId}
  AND e.state != 'DELETED'

    AND e.state = #{state}

ORDER BY e.create_time DESC, e.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM errand_order
WHERE taker_id = #{userId}
  AND state != 'DELETED'

    AND state = #{state}

SELECT COUNT(1)
FROM errand_order_event
WHERE actor_id = #{actorId}
  AND event_type = 'LOCK_ABANDONED'
  AND create_time >= #{since}

SELECT MAX(create_time)
FROM errand_order_event
WHERE actor_id = #{actorId}
  AND event_type = 'LOCK_ABANDONED'
  AND create_time >= #{since}

